<?php
namespace app\services;
use app\components\{Api,ApiException,BillingPolicy,MasterPolicy};
use yii\db\{Query,Expression,Exception as DbException};
/** Core is sole writer. Lock order: visit -> invoice -> payment key. */
final class BillingService
{
    private function db(){return \Yii::$app->db;}
    private function missing(): never {throw new ApiException(404,'NOT_FOUND','Tagihan atau kunjungan tidak ditemukan.');}
    private function conflict(string $code,string $message): never {throw new ApiException(409,$code,$message);}
    private function tx(callable $work): mixed {for($i=0;;$i++)try{return $this->db()->transaction($work);}catch(DbException $e){if(!in_array($e->errorInfo[0]??'',['40001','40P01'],true))throw $e;if($i>=2)throw new ApiException(503,'RETRY_LATER','Transaksi sibuk. Coba ulang dengan key yang sama.');usleep(20000*($i+1));}}
    private function visit(string $id,bool $write): array {
        if(!MasterPolicy::id($id))$this->missing();$v=$this->db()->createCommand('SELECT * FROM visits WHERE id=:id '.($write?'FOR UPDATE':'FOR SHARE'),[':id'=>$id])->queryOne();if(!$v||!in_array($v['status'],['ready_for_billing','completed'],true))$this->missing();return $v;
    }
    private function invoice(string $id,bool $lock=false): ?array {return $this->db()->createCommand('SELECT * FROM invoices WHERE visit_id=:id'.($lock?' FOR UPDATE':''),[':id'=>$id])->queryOne()?:null;}
    private function paid(string $invoice): int {return (int)(new Query())->from('payments')->where(['invoice_id'=>$invoice])->sum('amount');}
    private function audit(array $actor,string $id,string $action,?array $before,array $after,?string $reason=null): void {$this->db()->createCommand()->insert('audit_logs',['actor_id'=>$actor['id'],'action'=>$action,'entity_type'=>'visits','entity_id'=>$id,'before_data'=>$before===null?null:new \yii\db\JsonExpression($before, 'jsonb'),'after_data'=>new \yii\db\JsonExpression($after, 'jsonb'),'reason'=>$reason,'request_id'=>Api::id()])->execute();}
    private function lines(string $id): array {
        $v=(new Query())->from('visits')->where(['id'=>$id])->one();if(!$v)$this->missing();
        if((new Query())->from('prescriptions')->where(['visit_id'=>$id,'status'=>'pending'])->exists()||(new Query())->from('lab_orders')->where(['visit_id'=>$id,'status'=>'pending'])->exists())$this->conflict('SERVICES_PENDING','Pelayanan penunjang belum selesai.');
        $rows=$this->db()->createCommand("SELECT 'registration' AS category,id AS source_id,'Pendaftaran' AS description,registration_fee AS unit_price,1 AS quantity FROM visits WHERE id=:v1 UNION ALL SELECT 'procedure',id,name_snapshot,unit_price,quantity FROM visit_procedures WHERE visit_id=:v2 UNION ALL SELECT 'laboratory',i.id,i.name_snapshot,i.unit_price,1 FROM lab_order_items i JOIN lab_orders o ON o.id=i.lab_order_id WHERE o.visit_id=:v3 AND o.status='completed' UNION ALL SELECT 'medicine',i.id,i.name_snapshot,i.unit_price,i.quantity FROM prescription_items i JOIN prescriptions p ON p.id=i.prescription_id WHERE p.visit_id=:v4 AND p.status='dispensed' ORDER BY category,source_id",[':v1'=>$id,':v2'=>$id,':v3'=>$id,':v4'=>$id])->queryAll();
        foreach($rows as &$r){$r['source_id']=(string)$r['source_id'];$r['unit_price']=(string)$r['unit_price'];$r['quantity']=(int)$r['quantity'];}unset($r);return $rows;
    }
    private function storedLines(string $invoice): array {$rows=(new Query())->select(['category','source_id','description','unit_price','quantity'])->from('invoice_items')->where(['invoice_id'=>$invoice])->orderBy(['category'=>SORT_ASC,'source_id'=>SORT_ASC])->all();foreach($rows as &$r){$r['source_id']=(string)$r['source_id'];$r['unit_price']=(string)$r['unit_price'];$r['quantity']=(int)$r['quantity'];}unset($r);return $rows;}
    private function writeLines(string $invoice,array $lines): void {$db=$this->db();$db->createCommand()->delete('invoice_items',['invoice_id'=>$invoice])->execute();foreach($lines as $line)$db->createCommand()->insert('invoice_items',['invoice_id'=>$invoice,...$line])->execute();}
    private function complete(array $actor,string $id): void {if($this->db()->createCommand()->update('visits',['status'=>'completed','updated_at'=>new Expression('now()')],['id'=>$id,'status'=>'ready_for_billing'])->execute()===1)$this->audit($actor,$id,'complete_visit',['status'=>'ready_for_billing'],['status'=>'completed']);}
    /** Invoked inside a visit-locked transaction, including clinical and ancillary completion. */
    public function issueLocked(array $actor,string $id): void {
        $v=$this->visit($id,true);if($this->invoice($id,true))return;if($v['status']!=='ready_for_billing')$this->conflict('INVOICE_CLOSED','Kunjungan sudah selesai.');$lines=$this->lines($id);$total=BillingPolicy::total($lines);$db=$this->db();$no='INV-'.$db->createCommand("SELECT nextval('invoice_no_seq')")->queryScalar();
        $iid=(string)$db->createCommand('INSERT INTO invoices (visit_id,invoice_no,total_amount,created_by) VALUES (:v,:n,:t,:a) RETURNING id',[':v'=>$id,':n'=>$no,':t'=>$total,':a'=>$actor['id']])->queryScalar();$this->writeLines($iid,$lines);$this->audit($actor,$id,'issue_invoice',null,['invoice_id'=>$iid,'invoice_no'=>$no,'revision'=>1,'total_amount'=>(string)$total,'items'=>$lines]);if($total===0)$this->complete($actor,$id);
    }
    /** No invoice yet is permitted for legacy ready visits. Must be called under visit lock. */
    public function canReviseLocked(string $id,string $status): bool {$i=$this->invoice($id,true);return BillingPolicy::canRevise($status,$i!==null&&$this->paid((string)$i['id'])>0);}
    public function reviseLocked(array $actor,string $id,string $reason): void {
        if(!$this->canReviseLocked($id,$this->visit($id,true)['status']))$this->conflict('BILLING_LOCKED','Tagihan sudah menerima pembayaran atau selesai.');$i=$this->invoice($id,true);if(!$i){$this->issueLocked($actor,$id);return;}$iid=(string)$i['id'];$before=$this->storedLines($iid);$after=$this->lines($id);if($before===$after)return;$total=BillingPolicy::total($after);$rev=(int)$i['revision']+1;
        $this->writeLines($iid,$after);$this->db()->createCommand()->update('invoices',['total_amount'=>$total,'revision'=>$rev,'updated_at'=>new Expression('now()')],['id'=>$iid])->execute();$this->audit($actor,$id,'revise_invoice',['invoice_id'=>$iid,'revision'=>(int)$i['revision'],'total_amount'=>(string)$i['total_amount'],'items'=>$before],['invoice_id'=>$iid,'revision'=>$rev,'total_amount'=>(string)$total,'items'=>$after],$reason);if($total===0)$this->complete($actor,$id);
    }
    private function base(?string $onlyVisit=null): Query {$payments=(new Query())->select(['invoice_id','paid_amount'=>new Expression('SUM(amount)')])->from('payments')->groupBy('invoice_id');if($onlyVisit!==null)$payments->where(['in','invoice_id',(new Query())->select('id')->from('invoices')->where(['visit_id'=>$onlyVisit])]);return (new Query())->from(['v'=>'visits'])->innerJoin(['p'=>'patients'],'p.id=v.patient_id')->innerJoin(['c'=>'clinics'],'c.id=v.clinic_id')->leftJoin(['i'=>'invoices'],'i.visit_id=v.id')->leftJoin(['s'=>$payments],'s.invoice_id=i.id')->select(['visit_id'=>'v.id','visit_status'=>'v.status','v.visit_date','patient_name'=>'p.name','p.medical_record_no','clinic_name'=>'c.name','invoice_id'=>'i.id','i.invoice_no','i.revision','i.total_amount','i.created_at','i.updated_at','paid_amount'=>new Expression('COALESCE(s.paid_amount,0)')])->where(['v.status'=>['ready_for_billing','completed']]);}
    private function row(array $r): array {foreach(['visit_id','invoice_id','total_amount','paid_amount'] as $k)$r[$k]=$r[$k]===null?null:(string)$r[$k];$r['revision']=$r['revision']===null?null:(int)$r['revision'];$r['balance']=$r['total_amount']===null?null:(string)((int)$r['total_amount']-(int)$r['paid_amount']);foreach(['created_at','updated_at'] as $k)if($r[$k]!==null)$r[$k]=(new \DateTimeImmutable($r[$k]))->format(DATE_ATOM);$r['payment_status']=$r['invoice_id']===null?'unissued':BillingPolicy::status((int)$r['total_amount'],(int)$r['paid_amount']);return $r;}
    public function queue(array $input): array {$f=BillingPolicy::filters($input);$q=$this->base();if(isset($f['q']))$q->andWhere(['or',['ilike','p.name',$f['q']],['ilike','p.medical_record_no',$f['q']],['ilike','i.invoice_no',$f['q']]]);$condition=match($f['status']){'unissued'=>'i.id IS NULL','unpaid'=>'i.id IS NOT NULL AND COALESCE(s.paid_amount,0)=0 AND i.total_amount>0','partial'=>'COALESCE(s.paid_amount,0)>0 AND s.paid_amount<i.total_amount','paid'=>'i.id IS NOT NULL AND COALESCE(s.paid_amount,0)=i.total_amount',default=>null};if($condition)$q->andWhere($condition);$total=(int)(clone $q)->count();$rows=$q->orderBy(['v.visit_date'=>SORT_DESC,'v.id'=>SORT_DESC])->limit($f['per_page'])->offset(($f['page']-1)*$f['per_page'])->all();return ['data'=>array_map(fn($r)=>$this->row($r),$rows),'meta'=>['total'=>$total,'page'=>$f['page'],'per_page'=>$f['per_page'],'request_id'=>Api::id()]];}
    private function paymentRow(array $p): array {return ['id'=>(string)$p['id'],'receipt_no'=>$p['receipt_no'],'amount'=>(string)$p['amount'],'method'=>$p['method'],'cashier_name'=>$p['cashier_name'],'paid_at'=>(new \DateTimeImmutable($p['paid_at']))->format(DATE_ATOM)];}
    private function detail(string $id): array {$r=$this->base($id)->andWhere(['v.id'=>$id])->one();if(!$r)$this->missing();$r=$this->row($r);$iid=$r['invoice_id'];$r['items']=$iid?$this->storedLines($iid):[];$r['payments']=$iid?array_map(fn($p)=>$this->paymentRow($p),(new Query())->from(['p'=>'payments'])->innerJoin(['u'=>'users'],'u.id=p.cashier_id')->select(['p.*','cashier_name'=>'u.name'])->where(['p.invoice_id'=>$iid])->orderBy(['p.id'=>SORT_ASC])->all()):[];return $r;}
    public function get(string $id): array {return $this->tx(function()use($id){$this->visit($id,false);return $this->detail($id);});}
    public function issue(array $actor,string $id,array $body): array {if($body)throw new ApiException(422,'VALIDATION_ERROR','Body harus kosong.');return $this->tx(function()use($actor,$id){$this->visit($id,true);$this->issueLocked($actor,$id);return $this->detail($id);});}
    public function pay(array $actor,string $id,array $input,mixed $key): array {
        $b=BillingPolicy::payment($input,$key);$hash=BillingPolicy::hash($id,$b);return $this->tx(function()use($actor,$id,$b,$hash){$v=$this->visit($id,true);$i=$this->invoice($id,true);if(!$i)$this->conflict('INVOICE_REQUIRED','Terbitkan invoice terlebih dahulu.');$iid=(string)$i['id'];$db=$this->db();
            $db->createCommand('SELECT pg_advisory_xact_lock(682363,hashtext(:key))',[':key'=>$b['key']])->queryScalar();$old=(new Query())->from('payments')->where(['idempotency_key'=>$b['key']])->one();
            if($old){if(!BillingPolicy::same($old,$iid,(string)$actor['id'],$hash))$this->conflict('IDEMPOTENCY_CONFLICT','Key pembayaran telah digunakan untuk transaksi lain.');return ['invoice'=>$this->detail($id),'payment_id'=>(string)$old['id'],'replayed'=>true];}
            $paid=$this->paid($iid);$total=(int)$i['total_amount'];BillingPolicy::checkPayment($total,$paid,$b['amount'],(int)$i['revision'],$b['expected_revision'],$v['status']);$no='PAY-'.$db->createCommand("SELECT nextval('receipt_no_seq')")->queryScalar();$pid=(string)$db->createCommand('INSERT INTO payments (invoice_id,receipt_no,idempotency_key,payload_hash,amount,method,cashier_id) VALUES (:i,:n,:k,:h,:a,:m,:c) RETURNING id',[':i'=>$iid,':n'=>$no,':k'=>$b['key'],':h'=>$hash,':a'=>$b['amount'],':m'=>$b['method'],':c'=>$actor['id']])->queryScalar();
            $new=$paid+$b['amount'];$this->audit($actor,$id,'record_payment',['paid_amount'=>(string)$paid],['invoice_id'=>$iid,'payment_id'=>$pid,'receipt_no'=>$no,'amount'=>(string)$b['amount'],'method'=>$b['method'],'paid_amount'=>(string)$new,'revision'=>(int)$i['revision']]);if($new===$total)$this->complete($actor,$id);return ['invoice'=>$this->detail($id),'payment_id'=>$pid,'replayed'=>false];});
    }
}
